// Partner Resellers Retrieval
// Fetches indirect reseller relationships from Partner Center API

var accessToken = input.get("accessToken");

if (!accessToken || accessToken.trim() === "") {
    log.error("Access Token is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Access Token is required");
    output.set("StatusCode", 0);
    tags.trigger("error");
} else {
    try {
        var url = "https://api.partnercenter.microsoft.com/v1/relationships?relationship_type=IsIndirectCloudSolutionProviderOf";

        log.info("Fetching partner resellers");

        var response = http.get(url, {
            "Authorization": "Bearer " + accessToken.trim(),
            "Accept": "application/json"
        });

        output.set("StatusCode", response.statusCode);
        output.set("Body", response.body);

        if (response.statusCode >= 200 && response.statusCode < 300) {
            var data = json.parse(response.body);

            output.set("TotalCount", data.totalCount || 0);

            var resellers = data.items || [];
            output.set("Resellers", json.stringify(resellers));
            output.set("ResellerCount", resellers.length);

            // Count by state
            var activeCount = 0;
            var inactiveCount = 0;

            // Collect unique locations
            var locations = {};

            for (var i = 0; i < resellers.length; i++) {
                var reseller = resellers[i];

                // Count states
                if (reseller.state === "Active") {
                    activeCount++;
                } else {
                    inactiveCount++;
                }

                // Track locations
                var loc = reseller.location || "Unknown";
                if (!locations[loc]) {
                    locations[loc] = 0;
                }
                locations[loc]++;
            }

            output.set("ActiveCount", activeCount);
            output.set("InactiveCount", inactiveCount);

            // Convert locations to array of {location, count}
            var locationList = [];
            var locKeys = Object.keys(locations);
            for (var j = 0; j < locKeys.length; j++) {
                locationList.push({
                    location: locKeys[j],
                    count: locations[locKeys[j]]
                });
            }
            output.set("LocationBreakdown", json.stringify(locationList));
            output.set("UniqueLocations", locKeys.length);

            output.set("HasErrors", false);
            output.set("ErrorMessage", "");

            log.info("Successfully retrieved " + resellers.length + " resellers (" + activeCount + " active)");
            tags.trigger("success");
        } else {
            var errorMsg = "API returned status " + response.statusCode;
            try {
                var errorBody = json.parse(response.body);
                if (errorBody.message) errorMsg = errorBody.message;
                else if (errorBody.error_description) errorMsg = errorBody.error_description;
            } catch (e) {
                if (response.body) errorMsg = response.body.substring(0, 500);
            }

            log.error("Failed to retrieve resellers: " + errorMsg);
            output.set("HasErrors", true);
            output.set("ErrorMessage", errorMsg);
            tags.trigger("error");
        }
    } catch (ex) {
        log.error("Request failed: " + ex.message);
        output.set("HasErrors", true);
        output.set("ErrorMessage", "Request failed: " + ex.message);
        output.set("StatusCode", 0);
        tags.trigger("error");
    }
}
